    "stepByStepSolutionEn": [
      "1. Direct substitution gives the indeterminate form $0/0$.",
      "2. Multiply and divide by conjugate:",
      "   $$\\frac{(\\sqrt{1 + 2x} - 1)(\\sqrt{1 + 2x} + 1)}{x(\\sqrt{1 + 2x} + 1)} = \\frac{(1 + 2x) - 1}{x(\\sqrt{1 + 2x} + 1)} = \\frac{2x}{x(\\sqrt{1 + 2x} + 1)}$$",
      "3. Cancel $x \\neq 0$: $\\frac{2}{\\sqrt{1 + 2x} + 1}$.",
      "4. Take limit as $x \\to 0$: $\\frac{2}{\\sqrt{1} + 1} = \\frac{2}{2} = 1$."
    ],
    "stepByStepSolutionAr": [
      "١. التعويض المباشر يعطي كمية غير معينة ٠/٠.",
      "٢. بالضرب في المرافق بسطاً ومقاماً نحصل على: $\\frac{2x}{x(\\sqrt{1 + 2x} + 1)}$.",
      "٣. باختصار $x$: يتبقى $\\frac{2}{\\sqrt{1 + 2x} + 1}$.",
      "٤. بالتعويض $x = 0$: نجد أن النهاية = $\\frac{2}{2} = 1$."
    ],
    "teacherTipEn": "Alternatively, this limit represents the derivative of sqrt(1 + kx) at x = 0.",
    "teacherTipAr": "يمكن اعتبار هذه النهاية أيضاً تعريف مشتقة الدالة جذر(١ + k س) عند س = ٠."
