      "Subtract: $(3x^2 + 5x) - (3x^2 + 6x) = -x - 2$.",
      "Next term: $-x / x = -1$. Multiply: $-1(x + 2) = -x - 2$.",
      "Subtract: $(-x - 2) - (-x - 2) = 0$.",
      "So $f(x) = 3x - 1$ for $x \\neq -2$. The oblique asymptote is $y = 3x - 1$."
