    "questionAr": "متتالية معرفة بالحد $u_0 = 1$ وعلاقة تراجعية $u_{n+1} = \\sqrt{6 + u_n}$ لجميع $n \\ge 0$. بافتراض أن المتتالية متقاربة، أوجد نهايتها $L$.",
